def apply(D):
    n=0
    for d in D:
        add=[x for x in EXTRA.get(d['id'],[]) if x[1] not in [u for _,u in d['src']]]
        if not add: continue
        keep=[(t,u) for t,u in d['src'] if not re.search(r'front page|Where to look|search',t,re.I)]
        d['src']=add+keep; d.pop('_built',None); n+=1
    return n
